// This file is generated by AI.

// 设置读取与迁移的断言。
//
// 重点是两处历史数据的升级: v0.5.1 及以前只有"一个全局引擎目录", 最近项目也只有路径。
// 迁移写错的后果是用户升级后丢失引擎配置或整个最近项目列表。

import { describe, expect, it } from 'vitest';

import { resolveProjectEngine } from '../src/lib/engine';
import { defaultSettings, normalizeSettings } from '../src/lib/settings';

describe('normalizeSettings', () => {
  it('空数据回落到默认值', () => {
    const settings = normalizeSettings({});
    expect(settings.engines).toEqual([]);
    expect(settings.recentProjects).toEqual([]);
    expect(settings.editorFontSize).toBe(defaultSettings.editorFontSize);
    expect(settings.autoSave).toBe(true);
  });

  it('把旧的 enginePath 迁移成引擎列表', () => {
    const settings = normalizeSettings({ enginePath: 'C:\\engines\\WebGAL 4.6.4' });
    expect(settings.engines).toHaveLength(1);
    expect(settings.engines[0].path).toBe('C:\\engines\\WebGAL 4.6.4');
    expect(settings.engines[0].name).toBe('WebGAL 4.6.4');
    expect(settings.engines[0].version).toBeUndefined();
  });

  it('迁移过来的引擎不会成为任何项目的"默认" (绑定仍为空)', () => {
    const settings = normalizeSettings({ enginePath: 'C:\\engines\\WebGAL' });
    expect(resolveProjectEngine({ engines: settings.engines }, {}, 'C:\\proj')).toBeNull();
  });

  it('已有引擎列表时忽略旧的 enginePath (不重复添加)', () => {
    const settings = normalizeSettings({
      enginePath: 'C:\\old',
      engines: [{ id: 'eng-1', name: 'WebGAL', version: '4.6.4', path: 'C:\\new' }],
    });
    expect(settings.engines).toHaveLength(1);
    expect(settings.engines[0].path).toBe('C:\\new');
  });

  it('丢弃结构不完整的引擎条目', () => {
    const settings = normalizeSettings({
      engines: [{ id: 'eng-1', path: 'C:\\ok', name: 'OK' }, { id: 'eng-2' }, null],
    });
    expect(settings.engines.map((engine) => engine.id)).toEqual(['eng-1']);
  });

  it('把旧的最近项目字符串数组升级成记录', () => {
    const settings = normalizeSettings({ recentProjects: ['C:\\a', 'C:\\b'] });
    expect(settings.recentProjects.map((item) => item.path)).toEqual(['C:\\a', 'C:\\b']);
    expect(settings.recentProjects[0].name).toBeUndefined();
  });

  it('保留其余字段并丢弃损坏的模板条目', () => {
    const settings = normalizeSettings({
      autoSave: false,
      editorFontSize: 18,
      templates: [{ id: 'tpl-1', name: '深海', path: 'C:\\tpl' }, { name: '缺 id' }],
    });
    expect(settings.autoSave).toBe(false);
    expect(settings.editorFontSize).toBe(18);
    expect(settings.templates.map((template) => template.id)).toEqual(['tpl-1']);
  });
});
